; Data section
; Everything after 0x6C9D is data (no call targets beyond this point)

; ===== Variable definitions (DS-relative addresses) =====
; These EQU constants give symbolic names to memory locations used in code.

; Lattice C runtime variables (low memory, within code segment)
dos_version     equ 0x0f        ; byte - DOS major version (from INT 21h/30h)
saved_ss        equ 0x11        ; word - saved SS register value
initial_sp      equ 0x13        ; word - initial SP after setup
stack_top       equ 0x15        ; word - top of stack (for overflow handler)
stack_limit     equ 0x17        ; word - stack overflow check threshold
stdin_redir     equ 0x19        ; 32 bytes - stdin redirect filename buffer
stdout_redir    equ 0x39        ; byte - first char of stdout redirect path
psp_segment     equ 0x5b        ; word - PSP segment (saved from ES at entry)
heap_base_off   equ 0x5d        ; word - heap base offset (initial heap_offset value)
heap_start_seg  equ 0x5f        ; word - heap start segment
heap_offset     equ 0x61        ; word - current heap allocation offset from base
heap_current_seg equ 0x63       ; word - heap current allocation segment
heap_size       equ 0x65        ; word - heap size in paragraphs
heap_remainder  equ 0x67        ; word - heap remaining bytes (fractional paragraph)
env_string_off  equ 0x6b        ; word - environment string pointer (offset)
env_segment     equ 0x6d        ; word - environment segment
program_name_off equ 0x6f       ; word - program name pointer offset in environment
fpu_present     equ 0x7b        ; byte - 1 if FPU (8087) detected, 0 otherwise
fpu_status      equ 0x7c        ; word - FPU status word from FNSTSW
dos_error_code  equ 0x80        ; word - DOS error code (used by DOS wrappers)
requested_stack_size equ 0xe0   ; word - stack size from command line =N parameter

; Error message strings (DS-relative offsets, used with INT 21h/09h)
; Strings are '$'-terminated with CR/LF, located at 0x6D22 in code section
err_invalid_stack_size equ 0x82 ; "Invalid stack size\r\n$"
err_invalid_redirect   equ 0x97 ; "Invalid I/O redirection\r\n$"
err_insufficient_memory equ 0xb1 ; "Insufficient memory\r\n$"
err_stack_overflow     equ 0xc7 ; "*** STACK OVERFLOW ***\r\n$"

; C runtime globals
argc            equ 0xe43e      ; word - parsed argument count (max 32)
argv            equ 0xe440      ; word[32] - parsed argument vector (pointers to strings)

; Lattice C _iob[] entries (14-byte I/O control blocks)
iob_stdin       equ 0xe1b0      ; stdin I/O block
iob_stdout      equ 0xe1be      ; stdout I/O block
iob_stderr      equ 0xe1cc      ; stderr I/O block

; Stdio globals
stdio_flags     equ 0xe5c6      ; word - global text/binary mode flags
stdio_bufsiz    equ 0xe5c8      ; word - default I/O buffer size (512)
stdio_mode      equ 0xe5ca      ; word - mode flags

; FILE struct array (42 bytes each, 20 entries starting at 0xe5ce)
file_stdin      equ 0xe5ce      ; FILE struct for fd 0 (stdin)
file_stdout     equ 0xe5f8      ; FILE struct for fd 1 (stdout)
file_stderr     equ 0xe622      ; FILE struct for fd 2 (stderr)

; Joystick/input state (written by init_controls, read_joystick, read_joystick_buttons)
joystick_present equ 0xe196     ; byte - 1 if joystick detected at port 0x201
joy_x_lo_thresh  equ 0xe197     ; word - joystick X axis low threshold (left)
joy_x_hi_thresh  equ 0xe199     ; word - joystick X axis high threshold (right)
joy_y_lo_thresh  equ 0xe19b     ; word - joystick Y axis low threshold (up)
joy_y_hi_thresh  equ 0xe19d     ; word - joystick Y axis high threshold (down)
joy_button_state equ 0xe19f     ; word - combined direction+button bitmask
joy_axis_left    equ 0xe1a1     ; byte - 1 if joystick left
joy_axis_right   equ 0xe1a2     ; byte - 1 if joystick right
joy_axis_up      equ 0xe1a3     ; byte - 1 if joystick up
joy_axis_down    equ 0xe1a4     ; byte - 1 if joystick down
joy_btn_2        equ 0xe1a5     ; byte - 1 if button 2 pressed
joy_btn_1        equ 0xe1a6     ; byte - 1 if button 1 pressed
cpu_speed_count  equ 0xe1a7     ; word - CPU speed measurement (loop iterations per 7 timer ticks)

; File I/O state (used by open_file_slot, get_file_slot, show_insert_disk)
file_slot_count  equ 0xe5cc     ; word - number of file table slots allocated
file_table_base  equ 0xe5ce     ; start of file table (42 bytes per slot)
file_error_code  equ 0xe4be     ; word - last file operation error code

; Heap free-list pointers (used by reset_heap)
heap_free_head_a equ 0xe4b6     ; word - heap free-list head pointer A
heap_free_head_b equ 0xe4b8     ; word - heap free-list head pointer B
heap_free_head_c equ 0xe4ba     ; word - heap free-list head pointer C
heap_free_head_d equ 0xe4bc     ; word - heap free-list head pointer D

; Heap memory pool tracking (used by reset_heap on DOS 2+)
heap_pool_lo     equ 0xe4c0     ; word - heap pool size low word
heap_pool_hi     equ 0xe4c2     ; word - heap pool size high word

; Game state variables
input_advance   equ 0xdf44      ; word - input advance/skip flag (cleared on shutdown)
rand_temp       equ 0x421a      ; word - temporary storage for rand_range calculation

; Animation script compiler (used by load_anim_script / parse_anim_command)
anim_cmd_table  equ 0x1e8       ; word[14] - pointers to animation command name strings
anim_script_buf equ 0xbc83      ; buffer - animation script text read buffer
anim_fmt_int    equ 0xbc85      ; string - scanf format "%d"
anim_fmt_2int   equ 0xbc88      ; string - scanf format "%d %d"
anim_fmt_str    equ 0xbc91      ; string - scanf format for chg_fig params
anim_fmt_pos    equ 0xbc9d      ; string - scanf format for set_pos params
anim_script_size equ 0xbd02     ; word - total bytecode size from last load_anim_script call

; Camera/viewport
camera_x         equ 0xe4       ; word - camera scroll X position
camera_x_min     equ 0x108      ; word - camera X minimum bound
camera_x_max     equ 0x10a      ; word - camera X maximum bound

; Level/scene state
scene_param_e2   equ 0xe2       ; word - scene-specific parameter (1=special encounter active)
current_level    equ 0xea       ; word - current level/area (0-3)
player_facing    equ 0xec       ; word - player facing direction (bit 0: 0=left, 1=right)
anim_render_mode equ 0xee       ; word - animation render mode (1=normal, 2=transition)
game_mode        equ 0xf0       ; word - game mode (0=normal, 1=special)
player_faces_right equ 0xf2     ; word - 1 if player faces right
enemy_atk_freq   equ 0xf4       ; word - enemy attack frequency threshold (0-255)
enemy_aggressive equ 0xf6       ; word - 1 if enemy is in aggressive mode
combat_active    equ 0xf8       ; word - >1 when combat ends/transitions
combat_phase     equ 0xfa       ; word - 0=normal, 1=approach, 2=retreat
player_was_hit   equ 0xfc       ; word - 1 if player was just hit
enemy_was_hit    equ 0xfe       ; word - 1 if enemy was just hit
enemy_x_min      equ 0x100      ; word - enemy X minimum bound
player_x_min     equ 0x102      ; word - player X left boundary
player_x_max     equ 0x104      ; word - player X right boundary
encounter_target equ 0x106      ; word - target X position for encounter trigger
player_anim_id   equ 0x10c      ; word - player current animation ID
enemy_x          equ 0x10e      ; word - enemy X position
enemy_anim_id    equ 0x110      ; word - enemy current animation ID
enemy_facing     equ 0x112      ; word - enemy facing direction
player_hits_left equ 0x114      ; word - player hit points remaining / right wipe column count
enemy_health     equ 0x116      ; word - enemy health points (max 9) / left wipe column count
enemy_frozen     equ 0x118      ; word - countdown frames until enemy unfreezes
scene_locked     equ 0x11a      ; word - countdown frames until scene unlocks
hit_regen_rate_p equ 0x11c      ; word - player health regen rate (ticks between regen)
encounter_counter equ 0x11e     ; word - hit exchange counter during encounter
hit_regen_rate_e equ 0x120      ; word - enemy health regen rate (ticks between regen)
hit_regen_init_e equ 0x122      ; word - enemy health regen initial rate (reset value)
enemy_health_regen equ 0x124    ; word - enemy health recovery amount
hit_regen_timer_e equ 0x126     ; word - enemy health regen countdown timer
hit_regen_timer_p equ 0x128     ; word - player health regen countdown timer
scroll_counter   equ 0x12c      ; word - screen scroll step counter
scene_transition_pending equ 0x12e ; word - 1 if scene transition is pending
scene_index      equ 0x130      ; word - current scene/encounter index within level
scene_slot_flags equ 0x142      ; word[8] - per-scene-slot active flags
level_advance    equ 0x152      ; word - levels to advance (0=none, 3=skip to level 3)
approach_flag    equ 0x154      ; word - approach state (1=approach, 2=retreat, 3=trigger, 4=done)
anim_mode        equ 0x156      ; word - animation processing mode
player_y_off     equ 0x158      ; word - player Y offset
approach_timer   equ 0x166      ; word - approach/wait timer countdown
player_flag_170  equ 0x170      ; word - player state flag (blocks enemy health drain)
player_flag_172  equ 0x172      ; word - 1 if approach regen setup done
player_flag_174  equ 0x174      ; word - player state flag
combat_counter_a equ 0x16c      ; word - combat counter
combat_counter_b equ 0x16e      ; word - combat counter

; Player animation state
player_sprite_cmd equ 0xbb30    ; byte - player sprite update command
player_anim_ctr  equ 0xbb31     ; word - player animation counter
player_anim_buf  equ 0xbb33     ; buffer - player animation data
player_anim_end  equ 0xbb2e     ; word - player animation end pointer
player_x         equ 0xbcd5     ; word - player X position
player_anim_div_a equ 0xc3a0    ; word - player animation divisor
player_anim_div_b equ 0xc3a2    ; word - player animation dividend
anim_bg_counter  equ 0xc3a6     ; word - background scene counter (indexes into bg lookup tables)
player_frame_ptr equ 0xc3d2     ; word - player animation frame pointer
player_frame_bak equ 0xc3d4     ; word - player animation frame backup

; Enemy animation state
enemy_frame_ptr  equ 0xcde8     ; word - enemy animation frame pointer
enemy_frame_bak  equ 0xcdea     ; word - enemy animation frame backup

; Animation script interpreter state
script_running   equ 0xbcd0     ; byte - 1 while animation script is executing
anim_rel_pos_mode equ 0xbcd7    ; byte - relative position mode counter (0=absolute)
single_step_mode equ 0xbcd8     ; word - 1 if animation runs in single-step (debug) mode
saved_return_addr equ 0xbcde    ; word - saved return address for play_music_sequence
saved_level      equ 0xbcda     ; word - saved current_level during music callback
saved_camera_x   equ 0xbcdc     ; word - saved camera_x during music callback
saved_bp         equ 0xbce0     ; word - saved BP during music callback
delay_tick_target equ 0xbce2    ; word - target tick count for delay_ticks
delay_iter_count equ 0xbce4     ; word - remaining iterations for delay_with_input
script_pc        equ 0xbce6     ; word - animation script program counter (byte offset)
anim_jump_table  equ 0xbce8     ; word[14] - jump table for animation script opcodes
timer_mark_tick  equ 0xbcd1     ; word - timer tick recorded by timer_mark
anim_fig_bg      equ 0xbb32     ; byte - current background figure index

; Animation working variables
anim_write_off   equ 0xd5a4     ; word - animation data write offset
anim_temp_ptr    equ 0xd5a8     ; word - animation data temp pointer
enemy_active     equ 0xd5aa     ; word - 0=no enemy, 1=enemy present
enemy_y_off      equ 0xd5ac     ; word - enemy Y offset
player_dir_flag  equ 0xd5ae     ; byte - player direction flag
enemy_dir_flag   equ 0xd5b0     ; byte - enemy direction flag
anim_data_limit  equ 0xd5b2     ; word - animation data limit
enemy_defeated   equ 0xd64c     ; word - 1 if enemy defeated
wipe_prev_right  equ 0xd650     ; word - previous right wipe column count (for delta detection)
wipe_prev_left   equ 0xd652     ; word - previous left wipe column count (for delta detection)
trans_buf_left   equ 0xd654     ; 14 bytes - transition column data buffer (left)
trans_buf_right  equ 0xd662     ; 14 bytes - transition column data buffer (right)
gate_anim_left   equ 0xd670     ; byte - gate animation cooldown (left)
gate_anim_right  equ 0xd671     ; byte - gate animation cooldown (right)
anim_state_bb2a  equ 0xbb2a     ; word - animation state variable

; Cutscene/level transition state (used by cutscene_play)
cutscene_state   equ 0xd672     ; word - cutscene sub-state counter
ui_pending       equ 0xd674     ; word - 1 if UI element needs to be displayed
eagle_active     equ 0xd676     ; word - 1 if eagle encounter is active (level 2)
eagle_scroll_dir equ 0xd678     ; word - eagle scroll direction (+/- for left/right)
eagle_trigger    equ 0xd67a     ; word - 1 if eagle attack triggered
eagle_cooldown   equ 0xd67c     ; word - eagle cooldown counter
princess_rescued equ 0xd67e     ; word - 1 if princess rescue triggered (level 3)

; Character type table (used for whitespace detection in argv parsing)
; ctype_table   equ 0xe4c4    ; byte[256] - bit 3 = whitespace

; Sound/music player variables (used by wait_vsync music routines)
music_note_ptr  equ 0xd6fd      ; word - pointer to current note in music data
music_tempo_hi  equ 0xd706      ; byte - note duration (outer loop count)
music_tempo_lo  equ 0xd707      ; byte - note duration (inner timing)
music_vibrato   equ 0xd708      ; byte - vibrato amount (0=off, 0xFD nn=set)
music_note_cnt  equ 0xd709      ; byte - note repeat count
music_pitch     equ 0xd700      ; byte - base pitch period
music_pitch_a   equ 0xd701      ; byte - pitch counter A (channel 1)
music_pitch_b   equ 0xd702      ; byte - pitch counter B (channel 2)
music_period    equ 0xd703      ; byte - period divider
music_outer     equ 0xd704      ; byte - outer duration counter
music_inner     equ 0xd705      ; byte - inner duration counter (0xFF per cycle)

; PC speaker playback
speaker_delay   equ 0xd6f8      ; byte - sample delay for play_speaker_data
speaker_delay_cnt equ 0xd70c    ; byte - delay countdown (decremented per sample)
speaker_prev_bit equ 0xd70d     ; byte - previous bit state (edge detection)
busy_wait_delay_cnt equ 0xd70e      ; word - outer loop count for busy_wait_delay

; PCM audio sample buffer (256 bytes, loaded at runtime)
; play_speaker_data reads 256 bytes of 1-bit audio from here
speaker_pcm_buf equ 0xda56      ; byte[256] - PCM sample buffer (0xDA56-0xDB55)

